var GRP={POR:'POR',DC:'DIF',TD:'DIF',TS:'DIF',ED:'CEN',ES:'CEN',CDC:'CEN',CC:'CEN',COC:'CEN',AD:'ATT',AS:'ATT',AT:'ATT',ATT:'ATT'};
